# Token-Bucket Rate Limiter in TypeScript

## Design notes

**Continuous refill.** Each bucket stores `tokens` and `updatedAt`. On every access it is refilled lazily:

```
tokens = min(capacity, tokens + elapsed × rate)
```

There are no timers per key. Fractional tokens are kept, so the refill is exact rather than stepped.

**Concurrency in one Node process.** JavaScript runs one piece of code at a time on a single thread. Every read-modify-write of a bucket happens synchronously, with no `await` in between, so two callers can never interleave inside an update. `acquire()` reserves its tokens *before* it awaits. That way, concurrent waiters queue up FIFO behind each other instead of all waking up and racing for the same tokens.

**Eviction is lossless.** A bucket that has refilled to capacity behaves exactly like a key that has never been seen. Deleting it therefore changes no observable behavior. Two mechanisms keep the map small:

- **Incremental sweep.** The map is kept in least-recently-used order (a JavaScript `Map` preserves insertion order, and each access re-inserts the key). Every call checks a few of the oldest entries and drops the full ones. A bucket becomes full at most `(capacity + maxDebt) / rate` after its last access. So memory is bounded by the number of keys active within that window.
- **Hard cap (`maxKeys`).** This is a safety net against key-flooding. If the map is at the cap, the oldest bucket is evicted even if it isn't full. That resets the evicted key to full, which means the limiter lets it through (fails open). The trade-off is documented in the code. Size `maxKeys` above your expected number of active keys.
- **Optional timer.** `startSweeper()` runs a full sweep periodically, so memory is reclaimed even when traffic stops. The timer is `unref`'d so it doesn't keep the process alive.

**Clock.** The clock is injectable and defaults to `performance.now()`, which is monotonic. If time ever appears to go backwards, the limiter treats elapsed time as zero rather than creating tokens.

## `src/tokenBucket.ts`

```ts
export interface Clock {
  /** Milliseconds. Should be monotonic (performance.now() by default). */
  now(): number;
}

export type Sleep = (ms: number) => Promise<void>;

export interface TokenBucketOptions {
  /** Max tokens a bucket can hold (burst size). */
  capacity: number;
  /** Tokens added per second, continuously. */
  refillPerSecond: number;
  /** Hard cap on tracked keys. Exceeding it force-evicts the LRU key (fails open). Default 100_000. */
  maxKeys?: number;
  /** How far below zero acquire() reservations may push a bucket. Default = capacity. */
  maxDebt?: number;
  /** Entries inspected for eviction on each call. Default 16. */
  sweepBatch?: number;
  clock?: Clock;
  sleep?: Sleep;
}

export interface ConsumeResult {
  allowed: boolean;
  /** Tokens left after this call (never negative in the result). */
  remaining: number;
  /** 0 if allowed; otherwise ms until this cost could succeed (Infinity if never). */
  retryAfterMs: number;
}

export interface AcquireOptions {
  /** Give up (without consuming) if the wait would exceed this. Default Infinity. */
  maxWaitMs?: number;
}

interface Bucket {
  tokens: number;    // may be negative while reservations are outstanding
  updatedAt: number; // ms
}

// Tolerance for float drift (e.g. 0.30000000000000004 vs 0.3).
const EPS = 1e-9;

const defaultClock: Clock = { now: () => performance.now() };
const defaultSleep: Sleep = (ms) => new Promise((r) => setTimeout(r, ms));

export class TokenBucketLimiter {
  private readonly buckets = new Map<string, Bucket>();
  private readonly capacity: number;
  private readonly ratePerMs: number;
  private readonly maxKeys: number;
  private readonly maxDebt: number;
  private readonly sweepBatch: number;
  private readonly clock: Clock;
  private readonly sleep: Sleep;
  private sweeper: ReturnType<typeof setInterval> | undefined;

  constructor(opts: TokenBucketOptions) {
    const { capacity, refillPerSecond } = opts;
    if (!(capacity > 0) || !Number.isFinite(capacity)) {
      throw new RangeError("capacity must be a positive finite number");
    }
    if (!(refillPerSecond > 0) || !Number.isFinite(refillPerSecond)) {
      throw new RangeError("refillPerSecond must be a positive finite number");
    }
    this.capacity = capacity;
    this.ratePerMs = refillPerSecond / 1000;
    this.maxKeys = opts.maxKeys ?? 100_000;
    this.maxDebt = opts.maxDebt ?? capacity;
    this.sweepBatch = opts.sweepBatch ?? 16;
    this.clock = opts.clock ?? defaultClock;
    this.sleep = opts.sleep ?? defaultSleep;
    if (!(this.maxKeys >= 1)) throw new RangeError("maxKeys must be >= 1");
    if (!(this.maxDebt >= 0)) throw new RangeError("maxDebt must be >= 0");
  }

  /** Number of keys currently tracked. */
  get size(): number {
    return this.buckets.size;
  }

  /**
   * Non-blocking: take `cost` tokens if available.
   * Fully synchronous, so atomic with respect to other callers in this process.
   */
  tryConsume(key: string, cost = 1): ConsumeResult {
    this.checkCost(cost);
    const now = this.clock.now();
    const b = this.touch(key, now);

    let result: ConsumeResult;
    if (b.tokens + EPS >= cost) {
      b.tokens = Math.max(b.tokens - cost, b.tokens > cost ? 0 : 0) || b.tokens - cost;
      if (Math.abs(b.tokens) < EPS) b.tokens = 0;
      result = { allowed: true, remaining: b.tokens, retryAfterMs: 0 };
    } else if (cost > this.capacity) {
      result = { allowed: false, remaining: Math.max(0, b.tokens), retryAfterMs: Infinity };
    } else {
      result = {
        allowed: false,
        remaining: Math.max(0, b.tokens),
        retryAfterMs: Math.ceil((cost - b.tokens) / this.ratePerMs),
      };
    }

    this.sweep(now, this.sweepBatch);
    return result;
  }

  /**
   * Waits until `cost` tokens are available, then resolves true.
   * Resolves false immediately (consuming nothing) if the wait would exceed
   * maxWaitMs, the reservation would exceed maxDebt, or cost > capacity.
   *
   * Tokens are reserved synchronously before awaiting, so concurrent waiters
   * are served FIFO and never over-admit.
   */
  async acquire(key: string, cost = 1, opts: AcquireOptions = {}): Promise<boolean> {
    this.checkCost(cost);
    if (cost > this.capacity) return false;
    const maxWaitMs = opts.maxWaitMs ?? Infinity;

    const now = this.clock.now();
    const b = this.touch(key, now);

    if (b.tokens + EPS >= cost) {
      b.tokens -= cost;
      if (Math.abs(b.tokens) < EPS) b.tokens = 0;
      this.sweep(now, this.sweepBatch);
      return true;
    }

    const waitMs = Math.ceil((cost - b.tokens) / this.ratePerMs);
    if (waitMs > maxWaitMs || b.tokens - cost < -this.maxDebt - EPS) {
      this.sweep(now, this.sweepBatch);
      return false;
    }

    b.tokens -= cost; // reserve: later callers see the debt and wait behind us
    this.sweep(now, this.sweepBatch);
    await this.sleep(waitMs);
    return true;
  }

  /** Remove every bucket that has fully refilled. O(n). Safe to call any time. */
  sweepAll(): number {
    return this.sweep(this.clock.now(), Infinity);
  }

  /** Periodically run sweepAll(). The timer is unref'd. Returns a stop function. */
  startSweeper(intervalMs = 60_000): () => void {
    this.stopSweeper();
    this.sweeper = setInterval(() => this.sweepAll(), intervalMs);
    this.sweeper.unref?.();
    return () => this.stopSweeper();
  }

  stopSweeper(): void {
    if (this.sweeper !== undefined) clearInterval(this.sweeper);
    this.sweeper = undefined;
  }

  /** Forget all state (e.g. in tests or on config reload). */
  clear(): void {
    this.buckets.clear();
  }

  // ---- internals ----

  private checkCost(cost: number): void {
    if (!(cost > 0) || !Number.isFinite(cost)) {
      throw new RangeError("cost must be a positive finite number");
    }
  }

  /** Get-or-create the bucket, apply refill, and mark it most-recently-used. */
  private touch(key: string, now: number): Bucket {
    let b = this.buckets.get(key);
    if (b === undefined) {
      if (this.buckets.size >= this.maxKeys) {
        // Hard cap: evict the LRU key even if not full. Its next request
        // starts with a full bucket (fails open). Size maxKeys generously.
        const oldest = this.buckets.keys().next();
        if (!oldest.done) this.buckets.delete(oldest.value);
      }
      b = { tokens: this.capacity, updatedAt: now };
      this.buckets.set(key, b);
      return b;
